class Cultivo extends DataClass implements Insertable<Cultivo> {
  final int id;
  final int predioId;
  final int plantaId;
  final int? compraId;

  /// FK opcional al lote (v4). Si es null, el cultivo usa `nombreLote` libre.
  final int? loteId;
  final String? nombreLote;
  final DateTime fechaSiembra;
  final DateTime? fechaCosechaEstimada;
  final double? areaBaseM2;
  final double? areaDisplay;
