  /// Último error legible por el usuario, null si el último intento fue OK.
  final String? lastError;
  const SyncTable(
      {required this.tabla,
      this.lastPulledAt,
      this.lastAttemptAt,
      this.lastError});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
