class Config extends DataClass implements Insertable<Config> {
  final int id;
  final String idioma;
  final String estiloUi;
  final String sistemaUnidades;
  final int? predioActivoId;
  final String monedaCodigo;
  final bool primeraEjecucion;
  final bool permisosSolicitados;
  final bool notificacionesHabilitadas;

  /// Cuántos días antes de la fecha programada se dispara el aviso.
  final int notificacionAntelacionDias;

  /// Opt-in para compartir reportes de patologías con la comunidad.
  final bool consentimientoPatologias;

  /// Token personal para EPPO Global Database (v11 — Fase 3i-B). Nullable:
  /// si es null la app solo usa el catálogo bundleado local.
  final String? eppoToken;
  final DateTime updatedAt;
  const Config(
      {required this.id,
      required this.idioma,
      required this.estiloUi,
