    map['sistema_unidades'] = Variable<String>(sistemaUnidades);
    if (!nullToAbsent || predioActivoId != null) {
      map['predio_activo_id'] = Variable<int>(predioActivoId);
    }
    map['moneda_codigo'] = Variable<String>(monedaCodigo);
    map['primera_ejecucion'] = Variable<bool>(primeraEjecucion);
    map['permisos_solicitados'] = Variable<bool>(permisosSolicitados);
    map['notificaciones_habilitadas'] =
        Variable<bool>(notificacionesHabilitadas);
    map['notificacion_antelacion_dias'] =
        Variable<int>(notificacionAntelacionDias);
    map['consentimiento_patologias'] = Variable<bool>(consentimientoPatologias);
    if (!nullToAbsent || eppoToken != null) {
      map['eppo_token'] = Variable<String>(eppoToken);
    }
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

